gEK(){return"\u0623\u0646\u062a \u0645\u0646 \u0633\u064a\u0631\u0633\u0644 \u0627\u0644\u0631\u0627\u0628\u0637. \u0627\u0644\u0634\u062e\u0635 \u064a\u0643\u062a\u0628 \u0628\u064a\u0627\u0646\u0627\u062a\u0647 \u0628\u0646\u0641\u0633\u0647 \u2014 \u0648\u0644\u0627 \u062a\u062f\u062e\u0644 \u0623\u0646\u062a \u0634\u064a\u0626\u064b\u0627."},
gET(){return"\u0627\u0644\u0635\u0644\u0629 (\u062e\u0627\u0644\u0629\u060c \u0635\u062f\u064a\u0642\u060c \u062c\u0627\u0631\u2026)"},
gEN(){return"\u0645\u0644\u0627\u062d\u0638\u0629 \u0644\u0643 (\xab\u062c\u062f\u062a\u064a\xbb)"},
gEC(){return"\u062d\u0627\u0645\u064d \u0623\u064a\u0636\u064b\u0627 (\u064a\u062a\u0644\u0642\u0649 \u0627\u0644\u062a\u0646\u0628\u064a\u0647\u0627\u062a)"},
gEB(){return"\u0648\u0635\u064a \u0642\u0627\u0646\u0648\u0646\u064a (\u0648\u062d\u0627\u0645\u064d \u062f\u0627\u0626\u0645\u064b\u0627)"},
gES(){return"\u0628\u0644\u063a \u0627\u0644\u062d\u062f \u0627\u0644\u0623\u0642\u0635\u0649 (5)"},
gEI(){return"\u0628\u0644\u063a \u0627\u0644\u062d\u062f \u0627\u0644\u0623\u0642\u0635\u0649 (2)"},
gEH(){return"\u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u062f\u0639\u0648\u0629"},
gEM(){return"\u0627\u0644\u062f\u0639\u0648\u0629 \u062c\u0627\u0647\u0632\u0629"},
gEL(){return"\u0623\u0631\u0633\u0644 \u0647\u0630\u0627 \u0627\u0644\u0631\u0627\u0628\u0637 \u0625\u0644\u0649 \u0627\u0644\u0634\u062e\u0635. \u064a\u064f\u0639\u0631\u0636 \u0645\u0631\u0629 \u0648\u0627\u062d\u062f\u0629 \u0648\u0635\u0627\u0644\u062d 14 \u064a\u0648\u0645\u064b\u0627."},
gEU(){return"\u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0631\u0627\u0628\u0637"},
gF9(){return"\u0623\u0646 \u062a\u0643\u0648\u0646 \u0634\u062e\u0635\u064b\u0627 \u0645\u0648\u062b\u0648\u0642\u064b\u0627"},
gEZ(){return"\u0623\u062f\u062e\u0644 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0630\u064a \u0623\u064f\u0631\u0633\u0644 \u0625\u0644\u064a\u0643."},
gEY(){return"\u0627\u0644\u0631\u0645\u0632"},
gv9(){return"\u0627\u0644\u062f\u0639\u0648\u0629 \u063a\u064a\u0631 \u0645\u0648\u062c\u0648\u062f\u0629 \u0623\u0648 \u0645\u0646\u062a\u0647\u064a\u0629."},
F2(a){return a+" \u064a\u0642\u062a\u0631\u062d \u0623\u0646 \u062a\u0643\u0648\u0646 \u0623\u062d\u062f \u0623\u0634\u062e\u0627\u0635\u0647 \u0627\u0644\u0645\u0648\u062b\u0648\u0642\u064a\u0646."},
F5(a,b){return"\u0623\u064f\u0631\u0633\u0644\u062a \u0627\u0644\u062f\u0639\u0648\u0629 \u0645\u0646 "+a+"\u060c \u0644\u0640 "+b+"."},
F6(a,b,c){return"\u0623\u064f\u0631\u0633\u0644\u062a \u0627\u0644\u062f\u0639\u0648\u0629 \u0645\u0646 "+a+" ("+b+" \u0644\u0640 "+c+")."},
